		<div class="wp-block-group drthai-service-card has-white-background-color has-background"><!-- wp:paragraph {"className":"drthai-service-card__number"} --><p class="drthai-service-card__number">01</p><!-- /wp:paragraph --><!-- wp:heading {"level":3,"fontSize":"large"} --><h3 class="wp-block-heading has-large-font-size">Khám chuyên khoa tiêu hóa</h3><!-- /wp:heading --><!-- wp:paragraph {"textColor":"ink-soft"} --><p class="has-ink-soft-color has-text-color">Bác sĩ trực tiếp tiếp nhận thông tin, khai thác tiền sử, thăm khám và đánh giá để định hướng bước kiểm tra hoặc theo dõi phù hợp.</p><!-- /wp:paragraph --></div>
		<!-- /wp:group -->
		<!-- wp:group {"backgroundColor":"white","className":"drthai-service-card","layout":{"type":"constrained"}} -->
