		<!-- /wp:group -->
		<!-- wp:group {"backgroundColor":"white","className":"drthai-service-card","layout":{"type":"constrained"}} -->
		<div class="wp-block-group drthai-service-card has-white-background-color has-background"><!-- wp:paragraph {"className":"drthai-service-card__number"} --><p class="drthai-service-card__number">03</p><!-- /wp:paragraph --><!-- wp:heading {"level":3,"fontSize":"large"} --><h3 class="wp-block-heading has-large-font-size">Đại tràng – hậu môn – trực tràng</h3><!-- /wp:heading --><!-- wp:paragraph {"textColor":"ink-soft"} --><p class="has-ink-soft-color has-text-color">Đánh giá các vấn đề thuộc đại tràng, trực tràng và vùng hậu môn để lựa chọn hướng thăm khám, kiểm tra và theo dõi phù hợp.</p><!-- /wp:paragraph --></div>
		<!-- /wp:group -->
		<!-- wp:group {"backgroundColor":"white","className":"drthai-service-card","layout":{"type":"constrained"}} -->
		<div class="wp-block-group drthai-service-card has-white-background-color has-background"><!-- wp:paragraph {"className":"drthai-service-card__number"} --><p class="drthai-service-card__number">04</p><!-- /wp:paragraph --><!-- wp:heading {"level":3,"fontSize":"large"} --><h3 class="wp-block-heading has-large-font-size">Gan – mật – tụy</h3><!-- /wp:heading --><!-- wp:paragraph {"textColor":"ink-soft"} --><p class="has-ink-soft-color has-text-color">Tư vấn và định hướng đánh giá các bất thường liên quan đến gan, đường mật và tụy dựa trên thăm khám cùng kết quả hiện có.</p><!-- /wp:paragraph --></div>
		<!-- /wp:group -->
		<!-- wp:group {"backgroundColor":"white","className":"drthai-service-card","layout":{"type":"constrained"}} -->
		<div class="wp-block-group drthai-service-card has-white-background-color has-background"><!-- wp:paragraph {"className":"drthai-service-card__number"} --><p class="drthai-service-card__number">05</p><!-- /wp:paragraph --><!-- wp:heading {"level":3,"fontSize":"large"} --><h3 class="wp-block-heading has-large-font-size">Nội soi dạ dày và đại tràng</h3><!-- /wp:heading --><!-- wp:paragraph {"textColor":"ink-soft"} --><p class="has-ink-soft-color has-text-color">Tư vấn chỉ định, chuẩn bị trước thủ thuật, các lưu ý sau nội soi và giải thích kết quả. Nội soi được thực hiện tại cơ sở khám bệnh, chữa bệnh phù hợp.</p><!-- /wp:paragraph --></div>
		<!-- /wp:group -->
		<!-- wp:group {"backgroundColor":"white","className":"drthai-service-card","layout":{"type":"constrained"}} -->
		<div class="wp-block-group drthai-service-card has-white-background-color has-background"><!-- wp:paragraph {"className":"drthai-service-card__number"} --><p class="drthai-service-card__number">06</p><!-- /wp:paragraph --><!-- wp:heading {"level":3,"fontSize":"large"} --><h3 class="wp-block-heading has-large-font-size">Tư vấn từ xa và theo dõi</h3><!-- /wp:heading --><!-- wp:paragraph {"textColor":"ink-soft"} --><p class="has-ink-soft-color has-text-color">Tư vấn từ xa có thể được bố trí sau khi xác nhận nhu cầu, phù hợp với phạm vi chuyên môn và tình trạng cụ thể. Bác sĩ sẽ hướng dẫn khi nào cần chuyển sang thăm khám trực tiếp.</p><!-- /wp:paragraph --></div>
